<?php require dirname(__DIR__).'/core/bootstrap.php';$u=auth();$admin=false;require ROOT.'/includes/panel.php';?><h1>Downloads.</h1><p class="muted">Arquivos liberados para suas licenças ativas. Atualizações são disponibilizadas pela equipe.</p><?php $fs=rows('SELECT f.id,f.name,f.size,f.sha256,f.created_at,p.name product FROM files f JOIN products p ON p.id=f.product_id WHERE EXISTS (SELECT 1 FROM licenses l WHERE l.user_id=? AND l.product_id=f.product_id AND l.status=\'active\' AND (l.expires_at IS NULL OR l.expires_at>=?)) ORDER BY f.id DESC',[$u['id'],date('Y-m-d')]);foreach($fs as $f):?><article class="card"><h3><?=e($f['product'])?></h3><p><?=e($f['name'])?> • <?=number_format($f['size']/1024,1,',','.')?> KB</p><p class="small" style="overflow-wrap:anywhere">SHA-256: <?=e($f['sha256'])?></p><a class="primary btn" href="<?=e(url('baixar.php?id='.$f['id']))?>">Baixar arquivo ↗</a></article><?php endforeach;if(!$fs):?><div class="empty">Nenhum arquivo liberado no momento.</div><?php endif;require ROOT.'/includes/endpanel.php';?>
